async createOrder(dto: CreateOrderDto) {
  // BUG: two systems, no shared transaction. A crash between these loses the event.
  const order = await this.orders.save(dto);
  this.client.emit('order.created', { orderId: order.id, items: order.items });
  return order;
}

model.en:
async createOrder(dto: CreateOrderDto) {
  return this.dataSource.transaction(async (manager) => {
    const order = await manager.getRepository(Order).save(dto);
    await manager.getRepository(OutboxEvent).insert({
      aggregateId: order.id,
      type: 'order.created',
      payload: JSON.stringify({ orderId: order.id, items: order.items }),
      // status defaults to 'pending'; a relay publishes it and marks it 'sent'
    });
    return order; // order row + outbox row commit together, or neither
  });
}

Why: the event is no longer emitted to the broker inline. Instead it is INSERTed into an outbox table inside the SAME transaction as the order row, through manager.getRepository so both writes share one commit. A crash now leaves either both rows or neither — never an order without its event. A separate relay (polling publisher or Debezium CDC) reads pending outbox rows and publishes order.created to the broker at-least-once, so the event survives the crash as a durable DB row. Do NOT keep this.client.emit inside createOrder; that is the bug being removed.

